const $=s=>document.querySelector(s);const lanes=[...document.querySelectorAll('.lane')];let best=Number(localStorage.getItem('pulse-path-best')||0),score=0,lives=3,level=1,hits=0,streak=0,notes=[],running=false,lastSpawn=0,raf=0;const travel=1650,hitWindow=155,scoreBox=$('#score');$('#best').textContent=best;function hud(){$('#score').textContent=score;$('#lives').textContent='● '.repeat(lives).trim();$('#level').textContent=`LEVEL ${level}`;$('#streak').textContent=`${streak} STREAK · ${Math.min(5,1+Math.floor(streak/10))}×`}function spawn(now){const lane=Math.floor(Math.random()*4),charge=Math.random()<.14;notes.push({id:crypto.randomUUID(),lane,born:now,target:now+travel,charge,el:null});const el=document.createElement('div');el.className='note'+(charge?' charge':'');lanes[lane].append(el);notes.at(-1).el=el}function frame(now){if(!running)return;if(now-lastSpawn>Math.max(430,760-level*16)){spawn(now);lastSpawn=now}for(const n of [...notes]){const progress=(now-n.born)/travel,hitY=74,top=Math.min(90,Math.max(-5,progress*hitY));n.el.style.top=top+'%';if(now>n.target+hitWindow){n.el.remove();notes=notes.filter(x=>x!==n);lives--;streak=0;lanes[n.lane].classList.add('miss');setTimeout(()=>lanes[n.lane].classList.remove('miss'),160);if(lives<=0){end();return}}}hud();raf=requestAnimationFrame(frame)}function start(){cancelAnimationFrame(raf);notes.forEach(n=>n.el?.remove());notes=[];score=0;lives=3;level=1;hits=0;streak=0;running=true;lastSpawn=performance.now();$('#startScreen').classList.add('hidden');$('#endScreen').classList.add('hidden');hud();raf=requestAnimationFrame(frame)}function end(){running=false;cancelAnimationFrame(raf);notes.forEach(n=>n.el?.remove());notes=[];best=Math.max(best,score);localStorage.setItem('pulse-path-best',best);$('#best').textContent=best;$('#finalScore').textContent=`Score ${score} · Best ${best}`;$('#endScreen').classList.remove('hidden')}function tap(i){if(!running)return;const now=performance.now(),candidates=notes.filter(n=>n.lane===i),note=candidates.sort((a,b)=>Math.abs(a.target-now)-Math.abs(b.target-now))[0];lanes[i].classList.add('hit');setTimeout(()=>lanes[i].classList.remove('hit'),110);if(!note||Math.abs(note.target-now)>hitWindow)return;note.el.remove();notes=notes.filter(n=>n!==note);streak++;hits++;const multiplier=Math.min(5,1+Math.floor(streak/10));score+=(note.charge?20:10)*multiplier;if(hits%20===0){level++;if(lives<5)lives++;$('#toast').textContent=`LEVEL ${level} · BONUS LIFE`;setTimeout(()=>$('#toast').textContent='',900)}hud()}lanes.forEach(l=>l.addEventListener('pointerdown',e=>{e.preventDefault();tap(+l.dataset.lane)}));window.addEventListener('keydown',e=>{const keys={ArrowLeft:0,a:0,ArrowDown:1,s:1,ArrowUp:2,k:2,ArrowRight:3,l:3,'1':0,'2':1,'3':2,'4':3};const key=e.key.length===1?e.key.toLowerCase():e.key;if(key in keys){e.preventDefault();tap(keys[key])}});$('#start').onclick=start;$('#again').onclick=start;hud();
